// ─── File: .../service/SafeSipService.java ───
// @Lock + isolation TOGETHER: see committed data AND lock the row
package com.bank.sip.service;

import com.bank.sip.dto.SipDeductionRequest;
import com.bank.sip.model.InvestorAccount;
import com.bank.sip.repository.InvestorAccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class SafeSipService {

    private final InvestorAccountRepository accountRepo;

    /**
     * SAFE: READ_COMMITTED isolation + @Lock(PESSIMISTIC_WRITE) on query.
     *
     * Isolation (READ_COMMITTED): this TX only sees committed data.
     * @Lock(PESSIMISTIC_WRITE): SELECT ... FOR UPDATE — locks the row.
     *
     * Thread-1: SELECT ... FOR UPDATE → locks INV-001. Read balance = 500000.
     * Thread-2: SELECT ... FOR UPDATE → WAITS (row locked by Thread-1).
     * Thread-1: Deduct 10000 → balance = 490000. COMMIT. Lock released.
     * Thread-2: Now reads balance = 490000 (latest committed). Deduct 10000 → 480000. COMMIT.
     * Final: 480000 (Recommended) (both deductions applied correctly)
     *
     * Isolation and @Lock are COMPLEMENTARY:
     * - Isolation = what you SEE (DB-wide policy)
     * - @Lock = what you HOLD (row-specific lock)
     */
    @Transactional(isolation = Isolation.READ_COMMITTED, rollbackFor = Exception.class)
    public String deductSafe(SipDeductionRequest request) {
        String thread = Thread.currentThread().getName();

        InvestorAccount account = accountRepo.findByIdForUpdate(request.accountId())
            .orElseThrow();  // SELECT ... FOR UPDATE — row locked!

        log.info("[SAFE] [{}] Read balance={} (row LOCKED — other threads wait)",
            thread, account.getBalance());

        account.deductSip(request.amount(), request.currentNav());
        accountRepo.save(account);

        log.info("[SAFE] [{}] Saved balance={} (no lost update possible)",
            thread, account.getBalance());
        return "SAFE: " + account.getBalance().toString();
    }
}
