class SafeSipServiceTest {

    @Mock InvestorAccountRepository accountRepo;
    @InjectMocks SafeSipService service;

    @Test
    void shouldDeductWithPessimisticLock() {
        InvestorAccount account = mock(InvestorAccount.class);
        when(account.getBalance()).thenReturn(new BigDecimal("500000"));
        when(accountRepo.findByIdForUpdate("INV-001")).thenReturn(Optional.of(account));

        service.deductSafe(new SipDeductionRequest("INV-001", new BigDecimal("10000"), new BigDecimal("45")));

        verify(account).deductSip(new BigDecimal("10000"), new BigDecimal("45"));
        verify(accountRepo).save(account);
        // findByIdForUpdate = SELECT ... FOR UPDATE → row locked during TX
    }
